import workcell

def move(x, y, z):
    r = workcell.call("arm", "move", f"{x:.2f}", f"{y:.2f}", f"{z:.2f}")
    if not r.ok:
        print("MOVE FAIL", r.text)
    return r

def step(dz):
    r = workcell.call("arm", "step", f"{dz:.2f}")
    return r

def read():
    return workcell.call("ft", "read", "200")

def find_contact(x, y, z_start=130, z_clear=140):
    """Approach from z_start, step down until Fz>0.5, return contact info, then retract to z_clear."""
    r = move(x, y, z_start)
    if not r.ok:
        return {"error": r.text}
    # coarse steps of 5 until force or z too low
    z = None
    fz = None
    for i in range(30):
        r = step(-5)
        if not r.ok:
            print("STEP FAIL", r.text)
            move(x, y, z_clear)
            return {"error": r.text, "x": x, "y": y}
        z = r.data.get("z_mm")
        fz = r.data.get("fz_N")
        print(f"  x={x:.1f} y={y:.1f} z={z:.3f} Fz={fz:.2f}")
        if fz is not None and fz > 0.4:
            break
        if z is not None and z < 20:
            break
    ft = read()
    info = {"x": x, "y": y, "z": z, "fz": fz, "ft": ft.data}
    # retract
    move(x, y, z_clear)
    return info

points = [
    (510, 70),
    (510, 90),
    (510, 20),
    (480, 40),
    (540, 40),
    (450, 40),
    (510, 0),
    (510, 110),
]
for p in points:
    print("POINT", p)
    info = find_contact(*p)
    print("RESULT", info)
    print("---")
